@startuml

class Song {
  + Title : string
  + Year : int
  + Length : double
  + Genre : string
}

class Artist {
  + Name : string
  + DateOfBirth : date
  + WebsiteURL : string
}

abstract class User {
  + ID : int
  + Name : string
  + Address : string
}

class RegularUser {
}

class BusinessUser {
  + VATNumber : string
}

class Single {
}

class Hit {
  + TrackNumber : int
}

class Album {
  + Title : string
}

class Suggestion {
  + SimilarityScore : double
}

User --|> RegularUser
User --|> BusinessUser

Artist "1" -- "*" Song
RegularUser "1" -- "*" Album
RegularUser "1" -- "*" Single
BusinessUser "1" -- "*" Single
BusinessUser "1" -- "*" Hit

Single --|> Song
Hit --|> Song

Album "1" *-- "1..*" Hit
RegularUser "1" -- "*" Suggestion
RegularUser "1" -- "*" Suggestion

@enduml

